cd /Users/marcel.a.n.navarro/.claude/projects/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa && python3 - <<'PY'
import json,re
f='5c24b3ae-3d74-44bb-b2dc-7bd6040b2107.jsonl'
pat=re.compile(r'(re-?copy|from scratch|start fresh|fresh copy|backwards reconstruction|re-port|start the build fresh|discard the 29|delete the 29|scrap)',re.I)
def flat(c):
    if c is None: return ''
    if isinstance(c,str): return c
    if isinstance(c,list):
        out=[]
        for b in c:
            if isinstance(b,dict):
                if b.get('type')=='text': out.append(b.get('text',''))
                elif b.get('type')=='thinking': out.append(b.get('thinking',''))
        return ' '.join(out)
    return ''
hits=[]
for i,line in enumerate(open(f)):
    if not pat.search(line): continue
    try: d=json.loads(line)
    except: continue
    txt=flat(d.get('message',{}).get('content'))
    for m in pat.finditer(txt):
        s=max(0,m.start()-300); hits.append((i,d.get('type'),txt[s:m.end()+300].replace('\n',' ')))
for i,t,h in hits[-12:]:
    print(f"--- line {i} [{t}] ---\n{h}\n")
print('total',len(hits))
PY

