import { chromium } from 'playwright';

const URL = 'http://localhost:3000/product/8637DS241';
// DS ships 402 (mobile) and 1440 (desktop) only. 768-1279 is undesigned - measured for
// stability/regression, NOT compared to a spec.
const VIEWPORTS = [
  { name: 'mobile-402  (DS)',        width: 402,  height: 900, spec: true },
  { name: 'tablet-768  (UNDESIGNED)', width: 768,  height: 900, spec: false },
  { name: 'tablet-1024 (UNDESIGNED)', width: 1024, height: 900, spec: false },
  { name: 'desktop-1440 (DS)',       width: 1440, height: 900, spec: true },
];

// Zimmermann rem scale, px at 16px root.
const SCALE = { '0.25rem':4,'0.5rem':8,'0.75rem':12,'1rem':16,'1.25rem':20,'1.5rem':24,'1.75rem':28,'2rem':32,'2.5rem':40,'3rem':48,'4rem':64 };
const OK_PX = new Set([0, ...Object.values(SCALE)]);

const IDS = ['product-content','product-name','product-price','product-description','product-meta','product-model-info','product-style-code'];

const browser = await chromium.launch();
const results = {};

for (const vp of VIEWPORTS) {
  const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
  await page.goto(URL, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('[data-testid="product-name"]', { timeout: 90000 });
  await page.waitForTimeout(1200); // let hydration settle

  results[vp.name] = await page.evaluate(({ IDS, OK_PX }) => {
    const okpx = new Set(OK_PX);
    const g = (id) => document.querySelector(`[data-testid="${id}"]`);
    const box = (el) => { if (!el) return null; const c = getComputedStyle(el); const r = el.getBoundingClientRect();
      return { tag: el.tagName.toLowerCase(), w: +r.width.toFixed(2), h: +r.height.toFixed(2), top: +r.top.toFixed(2), bottom: +r.bottom.toFixed(2),
        mt: c.marginTop, mb: c.marginBottom, pt: c.paddingTop, pb: c.paddingBottom, gap: c.rowGap, fs: c.fontSize, lh: c.lineHeight, display: c.display }; };

    const out = { elements: {}, offToken: [], gaps: {}, a11y: {} };
    for (const id of IDS) out.elements[id] = box(g(id));

    // vertical gaps between adjacent rendered boxes (LINE BOXES, not cap heights)
    const pair = (a, b) => { const A = g(a), B = g(b); if (!A || !B) return null;
      return +(B.getBoundingClientRect().top - A.getBoundingClientRect().bottom).toFixed(2); };
    out.gaps['name->price']        = pair('product-name','product-price');
    out.gaps['price->description'] = pair('product-price','product-description');
    out.gaps['meta gap (model->style)'] = g('product-meta') ? getComputedStyle(g('product-meta')).rowGap : null;
    out.gaps['meta paddingTop (accordion->model)'] = g('product-meta') ? getComputedStyle(g('product-meta')).paddingTop : null;

    // style code internal gap
    const sc = g('product-style-code');
    out.gaps['styleCode label->value'] = sc ? getComputedStyle(sc).columnGap || getComputedStyle(sc).gap : null;

    // description list treatment
    const ul = g('product-description')?.querySelector('ul');
    out.gaps['list paddingInlineStart'] = ul ? getComputedStyle(ul).paddingInlineStart : '(no <ul> in this product copy)';
    out.gaps['list marginBlockStart']   = ul ? getComputedStyle(ul).marginBlockStart : '(n/a)';
    out.gaps['list markers']            = ul ? getComputedStyle(ul).listStyleType : '(n/a)';

    // off-token sweep across our whole subtree
    const root = g('product-content')?.closest('div') || document.body;
    const scope = [g('product-content'), g('product-meta')].filter(Boolean);
    for (const s of scope) {
      for (const el of [s, ...s.querySelectorAll('*')]) {
        const c = getComputedStyle(el);
        for (const prop of ['marginTop','marginBottom','marginLeft','marginRight','paddingTop','paddingBottom','paddingLeft','paddingRight','rowGap','columnGap']) {
          const v = c[prop];
          if (!v || v === 'normal' || v === 'auto') continue;
          const px = parseFloat(v);
          if (Number.isNaN(px) || px === 0) continue;
          if (!okpx.has(Math.round(px * 100) / 100)) {
            out.offToken.push({ el: el.getAttribute('data-testid') || el.tagName.toLowerCase(), prop, value: v });
          }
        }
      }
    }

    // a11y
    const price = g('product-price');
    out.a11y.priceAriaLive   = price?.getAttribute('aria-live');
    out.a11y.priceAriaAtomic = price?.getAttribute('aria-atomic');
    out.a11y.priceText       = price?.textContent?.trim();
    out.a11y.nameTag         = g('product-name')?.tagName.toLowerCase();
    out.a11y.headingOutline  = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(h => `${h.tagName.toLowerCase()}: ${h.textContent.trim().slice(0,42)}`);
    out.a11y.h1Count         = document.querySelectorAll('h1').length;
    return out;
  }, { IDS, OK_PX: [...OK_PX] });

  await page.close();
}
await browser.close();
console.log(JSON.stringify(results, null, 2));
