import pathlib
p = pathlib.Path("overrides/app/utils/richText.test.tsx")
s = p.read_text()
anchor = "describe('parseRichText — nested same-name structure', () => {"
block = """describe('parseRichText — HTML comments', () => {
  // Regression: comments are not tags, so `TAG_RE` never matched them and the markers plus the
  // comment body rendered as visible copy. `longDescription` is authored in Business Manager,
  // where leaving a note in the markup is entirely plausible, so a shopper would have seen it.
  test.each([
    ['comment inside a paragraph is removed', '<p>A silk dress.<!-- check pricing --></p>', '<p>A silk dress.</p>'],
    ['comment between blocks is removed', '<p>a</p><!-- note --><p>b</p>', '<p>a</p><p>b</p>'],
    ['two comments in one block', '<p>a<!--x-->b<!--y-->c</p>', '<p>abc</p>'],
    ['unterminated comment drops to end of input', '<p>a</p><!-- dangling', '<p>a</p>'],
    ['comment cannot smuggle a script through as text', '<p>a<!--><script>alert(1)</script>--></p>', '<p>a</p>'],
  ])('%s', (_name, input, expected) => {
    expect(render(input)).toBe(expected);
  });
});

"""
assert anchor in s
p.write_text(s.replace(anchor, block + anchor, 1))
